from abc import ABCMeta, abstractmethod
from future.utils import with_metaclass


class RegistrationCondition(with_metaclass(ABCMeta)):
    @abstractmethod
    def __call__(self, callback, callbacks):
        pass


class Always(RegistrationCondition):
    def __call__(self, callback, callbacks):
        return True


class UniqueCallback(RegistrationCondition):
    def __call__(self, callback, callbacks):
        return callback not in callbacks
